def comps(G,skip):
    seen=set(); out=[]
    for i in range(len(G)):
        for j in range(len(G[0])):
            if G[i][j]!=skip and (i,j) not in seen:
                col=G[i][j]; st=[(i,j)]; c=[]
                seen.add((i,j))
                while st:
                    y,x=st.pop(); c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<len(G) and 0<=nx<len(G[0]) and G[ny][nx]==col and (ny,nx) not in seen:
